<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {Newspaper,RefreshCw,Search,ArrowUpRight,Radio,BookOpen} from 'lucide-vue-next'
import {api} from '../services/api'
import type {NewsRadar,NewsRadarItem,EventStudy} from '../types/radar'
import Pagination from '../components/Pagination.vue'
import {usePagination} from '../composables/usePagination'
import {formatTime,formatTradingDate} from '../utils/format'
import {instrumentPath} from '../utils/marketNavigation'

const news=ref<NewsRadar|null>(null),study=ref<EventStudy|null>(null)
const loading=ref(false),newsError=ref(''),studyError=ref('')
const tab=ref('news'),search=ref(''),tier=ref('PRIMARY'),source=ref('ALL'),topic=ref('全部'),caseSector=ref('全部板块')
const filtered=computed(()=>(news.value?.items??[]).filter(i=>(tier.value==='ALL'||i.sourceTier===tier.value)&&(source.value==='ALL'||i.sourceId===source.value)&&(topic.value==='全部'||i.topic===topic.value)&&(!search.value||`${i.title} ${i.publisher} ${i.relatedSymbols.join(' ')} ${i.eventTypes?.join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))))
const {items,page,total}=usePagination(filtered,12,[search,tier,source,topic])
const filteredCases=computed(()=>(study.value?.items??[]).filter(i=>caseSector.value==='全部板块'||i.sector===caseSector.value))
const {items:cases,page:casePage,total:caseTotal}=usePagination(filteredCases,3,[caseSector])
const caseSectors=computed(()=>['全部板块',...new Set(study.value?.items.map(i=>i.sector)??[])])
const {items:sources,page:sourcePage,total:sourceTotal}=usePagination(computed(()=>news.value?.sources??[]),6)
const {items:watches,page:watchPage,total:watchTotal}=usePagination(computed(()=>study.value?.watchSources??[]),6)
const primaryCount=computed(()=>news.value?.items.filter(i=>i.sourceTier==='PRIMARY').length??0)
const connected=computed(()=>news.value?.sources?.filter(i=>i.status==='READY').length??0)
const published=(i:NewsRadarItem)=>i.timePrecision==='DAY'?`${i.publishedAt.slice(0,10)}（仅日期）`:`${formatTradingDate(i.publishedAt)} ${formatTime(i.publishedAt).slice(-8)} 北京时间`
const pct=(v?:number|null)=>v==null?'缺数':`${v>0?'+':''}${v.toFixed(2)}%`
function similar(item:NewsRadarItem){return (news.value?.items??[]).filter(i=>i.id!==item.id&&i.relatedSymbols.some(s=>item.relatedSymbols.includes(s))&&i.eventTypes?.some(t=>item.eventTypes?.includes(t))).slice(0,3)}
let alive=true
async function load(){
  if(loading.value)return
  loading.value=true;newsError.value='';studyError.value=''
  await Promise.allSettled([
    api.radarNews().then(v=>{if(alive)news.value=v}).catch(e=>{if(alive)newsError.value=e instanceof Error?e.message:'消息暂不可用'}),
    api.eventStudy().then(v=>{if(alive)study.value=v}).catch(e=>{if(alive)studyError.value=e instanceof Error?e.message:'历史案例暂不可用'}),
  ])
  if(alive)loading.value=false
}
onMounted(()=>void load());onUnmounted(()=>{alive=false})
</script>
<template>
  <div class="news-desk page-stack">
    <section class="news-intro"><div><span class="eyebrow">从信息到证据</span><h2>先找原始发布，再看它改变了什么。</h2><p>把消息、传导条件和价格变化放在一起。官方发布也需要核对预期差、执行与反证。</p></div><button class="refresh" type="button" :disabled="loading" @click="load"><RefreshCw :size="15"/>{{loading?'读取中':'更新资料'}}</button></section>
    <section class="news-stats" aria-label="消息覆盖"><div><span>当前快照原始发布</span><strong>{{primaryCount}} <small>条</small></strong></div><div><span>本次读取成功</span><strong>{{connected}} <small>/ {{news?.sources?.length??'—'}} 个源</small></strong></div><div><span>人工核验事件与背景</span><strong>{{study?.items.length??'—'}} <small>例</small></strong></div><div><span>解读方式</span><strong class="rule-label">公开规则 <small>待验证</small></strong></div></section>
    <div class="desk-tabs" role="tablist" aria-label="消息中心模块"><button type="button" role="tab" :aria-selected="tab==='news'" @click="tab='news'"><Newspaper :size="16"/>消息与解读</button><button type="button" role="tab" :aria-selected="tab==='study'" @click="tab='study'"><BookOpen :size="16"/>历史大行情溯源</button><button type="button" role="tab" :aria-selected="tab==='sources'" @click="tab='sources'"><Radio :size="16"/>来源与监测利用</button></div>
    <p v-if="newsError||news?.status==='UNAVAILABLE'" class="notice" role="alert">{{newsError||'各来源暂未取得有效消息，请查看来源状态后重试。'}} <button type="button" @click="load">重试</button></p>
    <template v-if="tab==='news'">
      <div class="news-filters"><label class="search"><Search :size="15"/><input v-model="search" type="search" aria-label="搜索消息" placeholder="搜索标题、品种代码或事件类型"/></label><select v-model="tier" aria-label="来源级别"><option value="PRIMARY">官方与企业原始发布</option><option value="SECONDARY">媒体汇编</option><option value="ALL">全部来源</option></select><select v-model="source" aria-label="发布机构"><option value="ALL">全部发布机构</option><option v-for="s in news?.sources??[]" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="topic" aria-label="消息分类"><option v-for="t in ['全部','宏观政策','交易规则','产业资讯','海外事件']" :key="t">{{t}}</option></select></div>
      <p class="scope">{{news?.message}} 默认筛选原始发布；“全部来源”可对照媒体汇编。{{news?.status==='PARTIAL'?'部分来源读取失败，详情见来源页。':''}}</p>
      <p v-if="loading&&!news" role="status">正在独立采集各个来源…</p>
      <div class="news-items"><article v-for="item in items" :key="item.id" class="news-item"><header><span class="tier" :class="item.sourceTier?.toLowerCase()">{{item.sourceTier==='PRIMARY'?'一手发布':'媒体汇编'}}</span><b>{{item.publisher}}</b><span>{{item.topic}}</span><span v-if="item.sourceStatus==='CACHED'" class="cached">保留旧快照</span></header><h3><a :href="item.url" target="_blank" rel="noopener noreferrer">{{item.title}} <ArrowUpRight :size="15"/></a></h3><div class="timestamps"><time>原文 {{published(item)}}</time><span>采集 {{formatTime(item.fetchedAt)}}</span></div><div v-if="item.relatedSymbols.length" class="tags"><span>潜在传导品种</span><RouterLink v-for="s in item.relatedSymbols" :key="s" :to="instrumentPath(s)">{{s}} ↗</RouterLink></div><details class="interpretation"><summary>查看解读与关联 · {{item.verificationStatus??'待核验'}}</summary><p class="scope">{{item.interpretationBasis}}</p><div v-for="analysis in item.analysis??[]" :key="analysis.eventType" class="analysis"><h4>{{analysis.eventType}}</h4><p><b>传导路径：</b>{{analysis.chain}}</p><p><b>方向与反证：</b>{{analysis.conditions}}</p><div><b>下一步核对：</b><span v-for="check in analysis.checks" :key="check" class="check">{{check}}</span></div></div><div v-if="similar(item).length" class="related-news"><b>同一传导主题的其他原文</b><p class="scope">规则关联，不表示同一事件，也不计作独立交叉验证。</p><a v-for="related in similar(item)" :key="related.id" :href="related.url" target="_blank" rel="noopener noreferrer">{{related.publisher}} · {{related.title}} ↗</a></div><button type="button" class="text-button" @click="tab='study'">参考历史事件机制 ↗</button></details></article></div>
      <p v-if="!items.length&&!loading" class="empty">当前快照没有匹配消息，可调整来源或关键词。</p>
      <Pagination v-model:page="page" :page-size="12" :total="total" label="消息分页"/>
    </template>
    <template v-if="tab==='study'">
      <p v-if="studyError" class="notice" role="alert">{{studyError}} <button type="button" @click="load">重试历史研究</button></p>
      <div class="study-lead"><h3>找到了关键原始发布，但没有证明“绝对最早”。</h3><p>{{study?.scope}}</p><p>{{study?.methodology}}</p><select v-model="caseSector" aria-label="案例板块"><option v-for="s in caseSectors" :key="s">{{s}}</option></select></div>
      <article v-for="item in cases" :key="item.id" class="case-card"><header><span>{{item.sector}} · {{item.eventDate}}</span><b>{{item.role}}</b></header><h3>{{item.title}}</h3><p>{{item.facts}}</p><div class="case-evidence"><div><h4>可核验与不可证明</h4><p>{{item.earliestStatus}}</p><p>{{item.limitation}}</p></div><div><h4>应用到今天的雷达</h4><p>{{item.chain}}</p><p>{{item.use}}</p></div></div><div class="checks"><b>核验清单</b><span v-for="check in item.checks" :key="check">{{check}}</span></div><div class="case-sources"><div v-for="s in item.sources" :key="s.url"><span>{{s.publisher}} · {{s.publishedDate}} · {{s.precision}}</span><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title}} ↗</a><small>{{s.role}}</small></div></div><details class="price-study"><summary>查看事件前后主连变化 · 非交易收益</summary><div class="table-wrap"><table><thead><tr><th>品种</th><th>基准日 / 收盘</th><th>之前20日</th><th>之后第5日</th><th>之后第20日</th></tr></thead><tbody><tr v-for="w in item.windows??[]" :key="w.symbol"><td><RouterLink :to="instrumentPath(w.symbol)">{{w.symbol}}</RouterLink></td><td>{{w.baselineDate??'缺少事件前数据'}}<small>{{w.baselineClose??'—'}}</small></td><td>{{pct(w.before20Pct)}}</td><td>{{pct(w.after5Pct)}}<small>{{w.after5Date??'未覆盖'}}</small></td><td>{{pct(w.after20Pct)}}<small>{{w.after20Date??'未覆盖'}}</small></td></tr></tbody></table></div><p class="scope">前后窗口不证明因果；主连换月可产生跳变，不能用作实盘收益。缺数保留缺数，不补造历史。</p></details></article>
      <Pagination v-model:page="casePage" :page-size="3" :total="caseTotal" label="历史案例分页"/>
    </template>
    <template v-if="tab==='sources'">
      <section class="source-section"><h3>本次来源状态</h3><p class="scope">成功表示本次能读取有效条目，不表示新闻是刚刚发生或已交叉核验。保留快照显示原采集时间。</p><div class="source-grid"><article v-for="s in sources" :key="s.id"><header><h4><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.name}} ↗</a></h4><span :class="s.status==='READY'?'ok':'cached'">{{s.status==='READY'?'读取成功':s.status==='CACHED'?'保留旧快照':'读取失败'}}</span></header><p>{{s.scope}}</p><p>{{s.message}} · {{s.itemCount}} 条</p><time>采集 {{formatTime(s.fetchedAt)}} · 最近原文 {{formatTradingDate(s.latestPublishedAt)}}</time></article></div><Pagination v-model:page="sourcePage" :page-size="6" :total="sourceTotal" label="消息来源分页"/></section>
      <section class="source-section"><h3>从历史研究得到的来源优先级</h3><p class="scope">优先级按事件责任主体和可核验性设定，不代表经过统计验证的预测排名。尚未接入的入口明确标出。</p><div class="watch-list"><article v-for="s in watches" :key="s.name"><h4><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.name}} ↗</a></h4><p>{{s.scope}}</p><small>{{s.collection}}</small></article></div><Pagination v-model:page="watchPage" :page-size="6" :total="watchTotal" label="监测利用分页"/></section>
    </template>
  </div>
</template>
<style scoped>
.news-desk{gap:1.2rem}.news-intro{display:flex;justify-content:space-between;align-items:end;gap:1rem}.eyebrow{color:var(--color-accent);font-size:.7rem}.news-intro h2{font:500 clamp(1.5rem,3vw,2.3rem) var(--font-display);margin:.65rem 0}.news-intro p,.scope{color:var(--color-ink-secondary);font-size:.74rem;line-height:1.85}.refresh,.desk-tabs button{display:flex;gap:.5rem;align-items:center;border:1px solid var(--color-line);border-radius:.5rem;padding:.65rem .85rem;background:white;cursor:pointer;font-size:.75rem}.refresh{white-space:nowrap}.news-stats{display:grid;grid-template-columns:repeat(4,1fr);padding:1.15rem 0;border-block:1px solid var(--color-line);gap:1rem}.news-stats span{display:block;font-size:.66rem;color:var(--color-ink-secondary)}.news-stats strong{display:block;font:600 1.65rem var(--font-numeric);margin-top:.4rem}.news-stats small{font-size:.65rem;font-weight:400;color:var(--color-ink-secondary)}.news-stats .rule-label{font-size:1.2rem}.desk-tabs{display:flex;gap:.5rem;flex-wrap:wrap}.desk-tabs button[aria-selected=true]{background:var(--color-ink);color:white;border-color:var(--color-ink)}.news-filters{display:flex;gap:.6rem;flex-wrap:wrap}.news-filters select,.study-lead select{border:1px solid var(--color-line);border-radius:.45rem;padding:.6rem;font-size:.73rem;background:white;max-width:100%}.search{display:flex;gap:.5rem;align-items:center;flex:1;min-width:14rem;border:1px solid var(--color-line);border-radius:.45rem;padding:.6rem;background:white}.search input{width:100%;border:0;outline:0;background:none;font-size:.75rem}.search:focus-within{outline:2px solid var(--color-accent)}.news-items{display:grid;gap:.8rem}.news-item,.case-card,.source-section{padding:1.2rem;background:var(--color-surface,#fff);border:1px solid var(--color-line);border-radius:.7rem;min-width:0}.news-item header,.case-card header{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;font-size:.65rem;color:var(--color-ink-secondary)}.news-item header b{color:var(--color-ink);font-weight:500}.tier{padding:.2rem .45rem;border-radius:.3rem;background:#f0eee8}.tier.primary{background:#e6eee9;color:#315748}.news-item h3{margin:.75rem 0;font-size:1rem;line-height:1.7}.news-item h3 a,.case-sources a{color:var(--color-ink);text-decoration:none}.timestamps{display:flex;gap:1rem;flex-wrap:wrap;font-size:.63rem;color:var(--color-ink-tertiary)}.tags{display:flex;gap:.4rem;align-items:center;flex-wrap:wrap;margin:.75rem 0;font-size:.65rem}.tags a{padding:.2rem .5rem;background:var(--color-canvas,#f6f5f2);color:var(--color-accent);text-decoration:none;border-radius:.25rem}.interpretation{margin-top:.9rem;border-top:1px solid var(--color-line);padding-top:.8rem;font-size:.74rem;line-height:1.9}.interpretation summary,.price-study summary{cursor:pointer;color:var(--color-accent)}.analysis{background:#f7f8f5;padding:.9rem;border-radius:.45rem;margin-top:.75rem}.analysis h4{margin:0}.analysis p{margin:.4rem 0}.check{display:inline-block;margin:.25rem .3rem .25rem 0;padding:0 .35rem;border:1px solid var(--color-line);border-radius:.3rem}.related-news{margin-top:1rem}.related-news a{display:block;margin:.5rem 0;color:var(--color-accent)}.text-button{border:0;background:none;color:var(--color-accent);padding:.5rem 0;cursor:pointer}.study-lead{padding:.3rem 0 .8rem}.study-lead h3{font-size:1.1rem}.study-lead p,.case-card p{font-size:.76rem;line-height:1.9;color:var(--color-ink-secondary)}.case-card h3{font-size:1.05rem;line-height:1.7}.case-card h4{font-size:.78rem;margin:0}.case-evidence{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.case-evidence>div{background:#f7f8f5;border-radius:.45rem;padding:.9rem}.checks{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap;font-size:.69rem;margin:1rem 0}.checks span{border:1px solid var(--color-line);border-radius:.3rem;padding:.3rem .5rem}.case-sources{display:grid;gap:.65rem;border-top:1px solid var(--color-line);padding-top:.8rem}.case-sources span,.case-sources small{display:block;font-size:.63rem;color:var(--color-ink-tertiary);line-height:1.9}.case-sources a{display:block;font-size:.75rem;line-height:1.8}.price-study{font-size:.72rem;margin-top:1rem}.table-wrap{overflow:auto;margin-top:.8rem}table{width:100%;border-collapse:collapse;text-align:left;font-size:.7rem}th,td{padding:.6rem;border-bottom:1px solid var(--color-line);white-space:nowrap}td small{display:block;color:var(--color-ink-tertiary);margin-top:.3rem}td a,a{color:var(--color-accent)}.source-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem}.source-grid article{padding:.9rem;border:1px solid var(--color-line);border-radius:.5rem;min-width:0}.source-grid header{display:flex;align-items:center;justify-content:space-between;gap:.5rem;font-size:.65rem}.source-grid h4,.watch-list h4{margin:0;font-size:.78rem}.source-grid p,.watch-list p{font-size:.72rem;line-height:1.8}.source-grid time,.watch-list small{font-size:.64rem;color:var(--color-ink-secondary)}.ok{color:#356951}.cached,.notice{color:var(--color-warning)}.notice{background:var(--color-warning-soft);padding:.8rem;border-radius:.4rem;font-size:.76rem}.watch-list{display:grid;gap:.8rem}.watch-list article{padding:.8rem 0;border-bottom:1px solid var(--color-line)}.empty{padding:2rem;color:var(--color-ink-secondary);font-size:.8rem}@media(max-width:700px){.news-intro{align-items:start;flex-direction:column}.news-stats{grid-template-columns:1fr 1fr}.case-evidence,.source-grid{grid-template-columns:1fr}.news-item,.case-card,.source-section{padding:1rem}.news-filters select{flex:1}.search{min-width:100%}}
</style>
